//! Unicode emoji for nixcord: data (shortcodes, names, keywords, categories), text
//! segmentation, Discord-style search and Twemoji file names.
//!
//! Pure: no UI dependencies. The data is one compact string table generated by
//! `tools/gen_data.py` from emojibase-data (MIT) and indexed lazily on first use (a few
//! tens of KB of index; nothing is parsed from JSON at runtime).
//!
//! ```
//! use nixcord_emoji::{by_shortcode, emoji_runs, twemoji_name, TextOrEmoji};
//!
//! let (heart, _) = by_shortcode("heart").unwrap();
//! assert_eq!(heart.as_str(), "\u{2764}\u{fe0f}");
//! assert_eq!(twemoji_name(heart.as_str()), "2764");
//! let runs: Vec<_> = emoji_runs("hi \u{1f980}!").collect();
//! assert_eq!(runs, [TextOrEmoji::Text("hi "), TextOrEmoji::Emoji("\u{1f980}"), TextOrEmoji::Text("!")]);
//! ```
//!
//! Skin tones are not separate entries: an emoji that takes one says where the modifier
//! goes ([`Emoji::with_skin_tone`]), and lookups ignore modifiers and U+FE0F.

mod data;
#[cfg(test)]
mod tests;
mod text;

pub use text::{
    count_emoji_only, emoji_runs, is_emoji, replace_shortcodes, shortcode_query, EmojiRuns,
    TextOrEmoji,
};

use std::borrow::Cow;
use std::sync::OnceLock;

/// Twemoji release the image URLs point at (jdecked/twemoji, the maintained fork).
pub const TWEMOJI_VERSION: &str = "17.0.3";

/// 72x72 PNG of an emoji on jsDelivr, e.g. `.../72x72/2764.png` for ❤️.
pub fn twemoji_url(emoji: &str) -> String {
    format!(
        "https://cdn.jsdelivr.net/gh/jdecked/twemoji@v{TWEMOJI_VERSION}/assets/72x72/{}.png",
        twemoji_name(emoji)
    )
}

/// Twemoji's file name rule (`grabTheRightIcon` in twemoji's source): the code points in
/// lowercase hex joined with `-`, with U+FE0F removed unless the sequence contains a ZWJ
/// (U+200D). So keycaps lose their U+FE0F (`1️⃣` -> `31-20e3`) while ZWJ sequences keep
/// it (`🏳️‍🌈` -> `1f3f3-fe0f-200d-1f308`).
///
/// One asset breaks the rule: Twemoji ships "eye in speech bubble" (👁️‍🗨️) only under its
/// unqualified name `1f441-200d-1f5e8`.
pub fn twemoji_name(emoji: &str) -> String {
    if emoji.starts_with('\u{1F441}') && emoji.contains('\u{1F5E8}') && emoji.contains(ZWJ) {
        let bare: String = emoji.chars().filter(|&c| c != VS16).collect();
        if bare == "\u{1F441}\u{200D}\u{1F5E8}" {
            return "1f441-200d-1f5e8".into();
        }
    }
    let keep_vs = emoji.contains(ZWJ);
    let mut out = String::with_capacity(emoji.len() * 3);
    for c in emoji.chars() {
        if c == VS16 && !keep_vs {
            continue;
        }
        if !out.is_empty() {
            out.push('-');
        }
        out.push_str(&format!("{:x}", c as u32));
    }
    out
}

pub(crate) const ZWJ: char = '\u{200D}';
pub(crate) const VS16: char = '\u{FE0F}';

/// Fitzpatrick modifiers U+1F3FB..=U+1F3FF.
pub(crate) fn is_tone(c: char) -> bool {
    ('\u{1F3FB}'..='\u{1F3FF}').contains(&c)
}

/// Picker categories, in Discord's order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Category {
    People,
    Nature,
    Food,
    Activities,
    Travel,
    Objects,
    Symbols,
    Flags,
}

impl Category {
    pub const ALL: [Category; 8] = [
        Category::People,
        Category::Nature,
        Category::Food,
        Category::Activities,
        Category::Travel,
        Category::Objects,
        Category::Symbols,
        Category::Flags,
    ];

    pub fn label(self) -> &'static str {
        match self {
            Category::People => "People",
            Category::Nature => "Nature",
            Category::Food => "Food",
            Category::Activities => "Activities",
            Category::Travel => "Travel",
            Category::Objects => "Objects",
            Category::Symbols => "Symbols",
            Category::Flags => "Flags",
        }
    }

    /// A representative emoji for the category's rail icon.
    pub fn icon(self) -> &'static str {
        match self {
            Category::People => "\u{1F600}",
            Category::Nature => "\u{1F33F}",
            Category::Food => "\u{1F354}",
            Category::Activities => "\u{26BD}",
            Category::Travel => "\u{1F697}",
            Category::Objects => "\u{1F4A1}",
            Category::Symbols => "\u{2764}\u{FE0F}",
            Category::Flags => "\u{1F3C1}",
        }
    }

    fn from_digit(d: u8) -> Category {
        Category::ALL[(d as usize).min(7)]
    }
}

/// One record of the table: byte offsets into `data::DATA`.
struct Rec {
    start: u32,
    /// End of each of the 5 fields, relative to `start`.
    ends: [u16; 5],
    cat: u8,
    skin: u8,
    text_default: bool,
}

struct Table {
    recs: Vec<Rec>,
    /// (hash of the normalized sequence, record), sorted.
    seq: Vec<(u64, u16)>,
    /// (offset, len, record) of every shortcode, sorted by name.
    names: Vec<(u32, u8, u16)>,
    /// First record of each category (plus the end).
    cat_start: [u16; 9],
}

fn table() -> &'static Table {
    static T: OnceLock<Table> = OnceLock::new();
    T.get_or_init(build)
}

fn build() -> Table {
    let data = data::DATA;
    let mut recs = Vec::with_capacity(data::COUNT);
    let mut start = 0usize;
    for line in data.split('\n') {
        let mut ends = [0u16; 5];
        let mut k = 0;
        for (i, b) in line.bytes().enumerate() {
            if b == b'\t' && k < 4 {
                ends[k] = i as u16;
                k += 1;
            }
        }
        ends[4] = line.len() as u16;
        let flags = &line.as_bytes()[ends[0] as usize + 1..ends[1] as usize];
        let hex = |b: u8| (b as char).to_digit(16).unwrap_or(0) as u8;
        recs.push(Rec {
            start: start as u32,
            ends,
            cat: flags.first().map_or(0, |b| b - b'0'),
            skin: flags.get(1).map_or(0, |b| hex(*b)),
            text_default: flags.get(2) == Some(&b't'),
        });
        start += line.len() + 1;
    }
    let mut seq: Vec<(u64, u16)> = Vec::with_capacity(recs.len());
    let mut names = Vec::with_capacity(recs.len() * 2);
    let mut cat_start = [recs.len() as u16; 9];
    for (i, r) in recs.iter().enumerate() {
        seq.push((norm_hash(field(r, 0)), i as u16));
        let mut off = r.start as usize + r.ends[1] as usize + 1;
        for n in field(r, 2).split(' ') {
            if !n.is_empty() {
                names.push((off as u32, n.len() as u8, i as u16));
            }
            off += n.len() + 1;
        }
        let c = r.cat as usize;
        if cat_start[c] as usize > i {
            cat_start[c] = i as u16;
        }
    }
    // Categories without records start where the next one does.
    for c in (0..8).rev() {
        if cat_start[c] as usize == recs.len() {
            cat_start[c] = cat_start[c + 1];
        }
    }
    seq.sort_unstable();
    names.sort_unstable_by(|a, b| name_at(a).cmp(name_at(b)));
    Table {
        recs,
        seq,
        names,
        cat_start,
    }
}

fn field(r: &Rec, i: usize) -> &'static str {
    let from = if i == 0 {
        0
    } else {
        r.ends[i - 1] as usize + 1
    };
    let s = r.start as usize;
    &data::DATA[s + from..s + r.ends[i] as usize]
}

fn name_at(n: &(u32, u8, u16)) -> &'static str {
    &data::DATA[n.0 as usize..n.0 as usize + n.1 as usize]
}

/// Code points of `s` without U+FE0F and skin-tone modifiers.
fn normalized(s: &str) -> impl Iterator<Item = char> + '_ {
    s.chars().filter(|&c| c != VS16 && !is_tone(c))
}

fn norm_hash(s: &str) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for c in normalized(s) {
        h ^= c as u64;
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    h
}

/// A unicode emoji from the table (base form, no skin tone).
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct Emoji(u16);

impl std::fmt::Debug for Emoji {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Emoji({} :{}:)", self.as_str(), self.shortcode())
    }
}

impl Emoji {
    fn rec(self) -> &'static Rec {
        &table().recs[self.0 as usize]
    }

    /// Position in the table (category order, then Unicode's order).
    pub fn index(self) -> usize {
        self.0 as usize
    }

    /// The fully-qualified emoji (with U+FE0F where Unicode wants it).
    pub fn as_str(self) -> &'static str {
        field(self.rec(), 0)
    }

    /// Discord-style shortcodes without colons, most common first (`heart`, `red_heart`).
    pub fn shortcodes(self) -> impl Iterator<Item = &'static str> {
        field(self.rec(), 2).split(' ').filter(|s| !s.is_empty())
    }

    /// The primary shortcode.
    pub fn shortcode(self) -> &'static str {
        self.shortcodes().next().unwrap_or("")
    }

    /// Unicode name, e.g. "red heart".
    pub fn label(self) -> &'static str {
        field(self.rec(), 3)
    }

    /// Search keywords (besides the shortcodes and label).
    pub fn keywords(self) -> impl Iterator<Item = &'static str> {
        field(self.rec(), 4).split(' ').filter(|s| !s.is_empty())
    }

    pub fn category(self) -> Category {
        Category::from_digit(self.rec().cat)
    }

    pub fn supports_skin_tone(self) -> bool {
        self.rec().skin != 0
    }

    /// Shown as text unless followed by U+FE0F (e.g. ©, ❤ without the selector).
    pub fn text_by_default(self) -> bool {
        self.rec().text_default
    }

    /// This emoji with skin tone `tone` (1..=5, light to dark; 0 = default yellow).
    /// Emoji without skin tones are returned unchanged.
    pub fn with_skin_tone(self, tone: u8) -> Cow<'static, str> {
        let mask = self.rec().skin;
        if mask == 0 || !(1..=5).contains(&tone) {
            return Cow::Borrowed(self.as_str());
        }
        let modifier = char::from_u32(0x1F3FA + tone as u32).unwrap_or('\u{1F3FB}');
        let mut out = String::with_capacity(self.as_str().len() + 8);
        for (i, comp) in self.as_str().split(ZWJ).enumerate() {
            if i > 0 {
                out.push(ZWJ);
            }
            let mut chars = comp.chars();
            if i < 8 && mask >> i & 1 == 1 {
                if let Some(first) = chars.next() {
                    out.push(first);
                    out.push(modifier);
                    let rest = chars.as_str();
                    out.push_str(rest.strip_prefix(VS16).unwrap_or(rest));
                    continue;
                }
            }
            out.push_str(comp);
        }
        Cow::Owned(out)
    }
}

/// Number of emoji in the table.
pub fn len() -> usize {
    table().recs.len()
}

/// Every emoji, in picker order.
pub fn all() -> impl ExactSizeIterator<Item = Emoji> {
    (0..len() as u16).map(Emoji)
}

/// Emoji of one picker category, in order.
pub fn category(cat: Category) -> impl ExactSizeIterator<Item = Emoji> {
    let t = table();
    let c = cat as usize;
    (t.cat_start[c]..t.cat_start[c + 1]).map(Emoji)
}

/// The table entry for an emoji sequence, ignoring U+FE0F and skin-tone modifiers
/// (`👍🏽` finds 👍, `❤` finds ❤️).
pub fn find(seq: &str) -> Option<Emoji> {
    let t = table();
    let h = norm_hash(seq);
    let i = t.seq.partition_point(|&(k, _)| k < h);
    t.seq[i..]
        .iter()
        .take_while(|&&(k, _)| k == h)
        .map(|&(_, r)| Emoji(r))
        .find(|e| normalized(e.as_str()).eq(normalized(seq)))
}

/// Emoji for a shortcode (no colons, case-insensitive). `thumbsup_tone3` style names
/// return the base emoji and the tone (1..=5); plain names return tone 0.
pub fn by_shortcode(name: &str) -> Option<(Emoji, u8)> {
    let name = name.strip_prefix(':').unwrap_or(name);
    let name = name.strip_suffix(':').unwrap_or(name);
    let lower;
    let name = if name.bytes().any(|b| b.is_ascii_uppercase()) {
        lower = name.to_ascii_lowercase();
        lower.as_str()
    } else {
        name
    };
    if let Some(e) = exact(name) {
        return Some((e, 0));
    }
    let (base, tone) = name.rsplit_once("_tone")?;
    let tone: u8 = tone.parse().ok().filter(|t| (1..=5).contains(t))?;
    exact(base)
        .filter(|e| e.supports_skin_tone())
        .map(|e| (e, tone))
}

fn exact(name: &str) -> Option<Emoji> {
    let t = table();
    let i = t.names.partition_point(|n| name_at(n) < name);
    t.names
        .get(i)
        .filter(|n| name_at(n) == name)
        .map(|n| Emoji(n.2))
}

/// How a search result matched (lower is better).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum MatchKind {
    /// A shortcode equals the query.
    Exact,
    /// A shortcode starts with the query.
    Prefix,
    /// A word of a shortcode (split at `_`) starts with the query.
    Word,
    /// A keyword or a word of the name starts with the query.
    Keyword,
}

/// How well `query` (already lowercase, no colons) matches a name: Exact / Prefix / Word.
pub fn match_name(name: &str, query: &str) -> Option<MatchKind> {
    if query.is_empty() {
        return None;
    }
    if name.eq_ignore_ascii_case(query) {
        Some(MatchKind::Exact)
    } else if starts_with_ci(name, query) {
        Some(MatchKind::Prefix)
    } else if name
        .split(['_', '-'])
        .skip(1)
        .any(|w| starts_with_ci(w, query))
    {
        Some(MatchKind::Word)
    } else {
        None
    }
}

fn starts_with_ci(s: &str, prefix: &str) -> bool {
    s.len() >= prefix.len()
        && s.is_char_boundary(prefix.len())
        && s[..prefix.len()].eq_ignore_ascii_case(prefix)
}

/// Search like Discord's picker and autocomplete: exact shortcode first, then shortcode
/// prefix, then a word inside a shortcode, then keywords and name words. Ties go to the
/// shorter shortcode, then table order. Returns at most `limit` results with how each
/// one matched.
pub fn search(query: &str, limit: usize) -> Vec<(Emoji, MatchKind)> {
    let q = query
        .trim()
        .trim_matches(':')
        .to_lowercase()
        .replace(' ', "_");
    if q.is_empty() || limit == 0 {
        return Vec::new();
    }
    let mut hits: Vec<(MatchKind, usize, Emoji)> = Vec::new();
    for e in all() {
        let mut best: Option<(MatchKind, usize)> = None;
        for n in e.shortcodes() {
            if let Some(k) = match_name(n, &q) {
                if best.is_none_or(|b| (k, n.len()) < b) {
                    best = Some((k, n.len()));
                }
            }
        }
        if best.is_none() {
            let kw = e.keywords().any(|k| starts_with_ci(k, &q))
                || e.label()
                    .split([' ', '-', ':', ','])
                    .any(|w| starts_with_ci(w, &q));
            if kw {
                best = Some((MatchKind::Keyword, e.shortcode().len()));
            }
        }
        if let Some((k, l)) = best {
            hits.push((k, l, e));
        }
    }
    hits.sort_by_key(|&(k, l, e)| (k, l, e.0));
    hits.truncate(limit);
    hits.into_iter().map(|(k, _, e)| (e, k)).collect()
}
